import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;
public class Patch implements Opcodes{
 static int hooks;static final String P="dev/zomboid/firstaid/";
 static byte[] patch(byte[] b){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);int before=hooks;for(MethodNode m:c.methods){
  if(c.name.equals(P+"Assist")&&(m.name.equals("defib")||m.name.equals("message"))){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;m.instructions.add(new VarInsnNode(ALOAD,0));if(m.name.equals("message"))m.instructions.add(new VarInsnNode(ALOAD,1));m.instructions.add(new MethodInsnNode(INVOKESTATIC,P+"DownedSupport",m.name,m.desc,false));m.instructions.add(new InsnNode(m.name.equals("defib")?ARETURN:RETURN));hooks++;}
  if(c.name.equals("ichttt/mods/firstaid/client/ClientEventHandler")&&m.name.equals("clientTick")){m.instructions.insert(new MethodInsnNode(INVOKESTATIC,P+"UnconsciousClient","tick","()V",false));hooks++;}
 }if(before==hooks)return b;ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static void verify(byte[] b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 public static void main(String[]a)throws Exception{Map<String,byte[]> entries=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[] b=z.getInputStream(e).readAllBytes();entries.put(e.getName(),e.getName().endsWith(".class")?patch(b):b);}}if(hooks!=Integer.parseInt(a[3]))throw new IllegalStateException("hook count "+hooks);try(var files=Files.walk(Path.of(a[2]))){for(Path p:files.filter(p->p.toString().endsWith(".class")).toList())entries.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:entries.entrySet()){if(e.getKey().endsWith(".class")&&(e.getKey().startsWith(P)||e.getKey().contains("/turretpower/Link")||e.getKey().endsWith("ClientEventHandler.class")))verify(e.getValue());ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}System.out.println("Verified hooks="+hooks+" in "+a[1]);}
}
